#define TMIN 0.1
#define TMAX 150.
#define RAYMARCH_TIME 128
#define PRECISION .001
#define AA 3
#define PI 3.14159265

vec2 fixUV(in vec2 c)
{
    return(2.*c-iResolution.xy)/min(iResolution.x,iResolution.y);

}

float sdfSphere(in vec3 p)//球体
{
    return length(p) - .8 ;
}

float sdfRect(in vec3 p, in vec3 b)//方形
{
    vec3 d=abs(p)-b;
    return length(max(d,-.2))+min(max(d.x,max(d.y,d.z)),0.);//奇奇怪怪的

}

float sdfPlane(in vec3 p)
{
    return p.y;    
}

float map(in vec3 p)//合并
{
    float d=sdfSphere(p);
    d =min(d,sdfPlane(p+vec3(0.,1.,0.)));
    /*float h=sdfRect(p,vec3(0.));
    d =min(d,sdfPlane(p+vec3(0.,1.,0.))+(h,sdfRect(p,vec3(1.))));*/

    return d;

}

float rayMarch(in vec3 ro, in vec3 rd)//射线方向和源头
{
    float t=TMIN;
    for(int i=0;i<RAYMARCH_TIME &&t<TMAX;i++)
    {
        vec3 p=ro+t*rd;
        //float d=sdfSphere(p);//输出球体
        //float d=sdfRect(p,vec3(.8+.1*sin(iTime),.3+.2*cos(iTime),.3));//输出方形
        float d=map(p);
        if(d<PRECISION)
        {
            //return t;
            break;
        }
        t += d;
    }
    return t;
}

// https://iquilezles.org/articles/normalsSDF
vec3 calcNormal(in vec3 p)//光照
{
    const float h=0.0001;;
    const vec2 k= vec2 (1,-1);
  /* return normalize(k.xyy * sdfSphere(p + k.xyy * h) +
        k.yyx * sdfSphere(p + k.yyx * h) +
        k.yxy * sdfSphere(p + k.yxy * h) +
        k.xxx * sdfSphere(p + k.xxx * h));*/ 
     return normalize(k.xyy * map(p + k.xyy * h) +
        k.yyx * map(p + k.yyx * h) +
        k.yxy * map(p + k.yxy * h) +
        k.xxx * map(p + k.xxx * h));
}

mat3 setCamera(vec3 ta,vec3 ro,float cr)//摄像机围绕球体旋转
{
    vec3 z=normalize(ta-ro);
    vec3 cp=vec3(sin(cr) , cos(cr),0.);
    vec3 x= normalize(cross(z,cp));
    vec3 y=cross(x,z);
    return mat3(x,y,z);

}

// https://iquilezles.org/articles/rmshadows
float softShadow(in vec3 ro,in vec3 rd,float k)//软阴影
{
    float res=1.0;
    float ph=1e20;
    for(float t=TMIN;t<TMAX;)
    {

        float h =map(ro+rd*t);
        if(h<.01)
            return 0.0;
        float y =h*h/(2.0*ph);
        float d=sqrt(h*h-y*y);
        res=min(res,k*d/max(0.0,t-y));
        ph=h;
        t+=h;
    }
    return res;
}

vec3 render(vec2 uv )
{
    vec3 color =vec3(.05);//背景颜色
    vec3 ro =vec3 (2.*cos(iTime),1.,2.*sin(iTime));//球体旋转
    if(iMouse.z>0.001)//鼠标控制
    {
        float theta=iMouse.x/iResolution.x*2.*PI;
        ro=vec3(2.*cos(theta),1.+0.2*cos(iTime),2.*sin(theta));
    }
    vec3 ta=vec3(0.);//摄像机位置
    mat3 cam=setCamera(ta,ro,.1*sin(iTime));//摄像机运动
    vec3 rd =normalize(cam*vec3 (uv,1.));//球体大小
    float t=rayMarch(ro,rd);
    if(t<TMAX)
    {
        vec3 p=ro+t*rd;
        vec3 n= calcNormal(p);
        vec3 light =vec3 (2.*cos(iTime),2.,2.*sin(iTime+2.));//光线移动
        //vec3 light =vec3 (2.,2.,2.);

        float dif=clamp(dot(normalize(light-p),n),0.,1.);
        p+=PRECISION*n;
       // float st = softShadow(p,normalize(light-p),2.);//明显交界线

        dif *=softShadow(p,normalize(light-p),2.);//光线平滑
       /*float st=rayMarch(p,normalize(light-p));
        if(st<TMAX)//假阴影
        {
            dif*=.1; 
        }*/

        float amd=0.5+0.5*dot(n,vec3(0.,1.,0));//环境灯光亮度

        color=amd*vec3(0.05)+dif*vec3(.6);

    }
    return sqrt(color);//幂

}

void mainImage(out vec4 fragColor,in vec2 fragCoord)
{
    vec3 color=vec3(0.);
    for(int m =0;m<AA;m++)
    {
        for(int n=0; n<AA;n++)
        {
            vec2 offset=2.*(vec2(float(m),float(n))/float(AA)-0.5);
            vec2 uv = fixUV(fragCoord+offset);
            color += render(uv);
        }
    }
    fragColor=vec4(color/float(AA*AA),1.);
}
